import json, glob, numpy as np

def load_lz(path):
    d = json.load(open(path))
    return d.get("lz_star", d.get("lz_star_corrected"))

def bootstrap_cohens_d(clean_vals, contam_val, n_boot=10000, seed=42):
    rng = np.random.RandomState(seed)
    clean = np.array(clean_vals, dtype=float)
    n = len(clean)
    d_obs = (clean.mean() - contam_val) / clean.std(ddof=1)
    boot_ds = []
    for _ in range(n_boot):
        idx = rng.randint(0, n, size=n)
        bc = clean[idx]
        sd = bc.std(ddof=1)
        if sd > 0:
            boot_ds.append((bc.mean() - contam_val) / sd)
    boot_ds = np.array(boot_ds)
    return d_obs, np.percentile(boot_ds, 2.5), np.percentile(boot_ds, 97.5)

